function getSilhouetteNoImageSvg() {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" width="128" height="128">
    <rect width="128" height="128" rx="64" fill="#0d1117" />
    <ellipse cx="64" cy="56" rx="38" ry="46" fill="#1b2a4a" stroke="rgba(0,240,255,0.4)" stroke-width="1.5" />
    <path d="M64 26 C 54 26, 46 34, 46 45 C 46 56, 54 64, 64 64 C 74 64, 82 56, 82 45 C 82 34, 74 26, 64 26 Z" fill="#ffffff" opacity="0.92" />
    <path d="M38 92 C 38 74, 48 68, 64 68 C 80 68, 90 74, 90 92 Z" fill="#ffffff" opacity="0.92" />
    <rect x="16" y="94" width="96" height="22" rx="11" fill="#0d1117" stroke="#00f0ff" stroke-width="1.2" />
    <text x="64" y="109" fill="#00f0ff" font-size="10" font-weight="800" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" text-anchor="middle" letter-spacing="0.5">SIN IMAGEN</text>
  </svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

function isDefaultPlaceholderPhoto(url) {
  if (!url || typeof url !== 'string' || url.trim() === '' || url === 'null' || url === 'undefined') return true;
  const lower = url.toLowerCase();
  return lower.includes('default') || 
         lower.includes('placeholder') || 
         lower.includes('ui-avatars') || 
         lower.includes('dicebear') || 
         lower.includes('portrait_small') ||
         lower.includes('via.placeholder');
}

// Smart onerror fallback chain: Real Photo -> DiceBear
function onAvatarError(img, p) {
  if (!img._fallback1) {
    img._fallback1 = true;
    img.src = getSilhouetteNoImageSvg();
    return;
  }
  img.onerror = null;
}

function getTeamColor(team) {
  return TEAM_COLORS[team] || '#00e5ff'; // Default to cyan
}

function getPositionEs(pos) {
  if (!pos) return 'Mediocampista';
  const posUpper = String(pos).toUpperCase().trim();
  const map = {
    'GK': 'Portero (PO)',
    'PO': 'Portero (PO)',
    'POR': 'Portero (PO)',
    'CB': 'Defensa Central (DFC)',
    'DFC': 'Defensa Central (DFC)',
    'LB': 'Lateral Izquierdo (LI)',
    'LI': 'Lateral Izquierdo (LI)',
    'RB': 'Lateral Derecho (LD)',
    'LD': 'Lateral Derecho (LD)',
    'LWB': 'Carrilero Izquierdo (CAD)',
    'RWB': 'Carrilero Derecho (CAR)',
    'DM': 'Pivote Defensivo (MCD)',
    'MCD': 'Pivote Defensivo (MCD)',
    'CM': 'Mediocentro (MC)',
    'MC': 'Mediocentro (MC)',
    'AM': 'Mediapunta (MCO)',
    'MCO': 'Mediapunta (MCO)',
    'LM': 'Interior Izquierdo (MI)',
    'MI': 'Interior Izquierdo (MI)',
    'RM': 'Interior Derecho (MD)',
    'MD': 'Interior Derecho (MD)',
    'LW': 'Extremo Izquierdo (EI)',
    'EI': 'Extremo Izquierdo (EI)',
    'RW': 'Extremo Derecho (ED)',
    'ED': 'Extremo Derecho (ED)',
    'CF': 'Segundo Delantero (SD)',
    'SD': 'Segundo Delantero (SD)',
    'ST': 'Delantero Centro (DC)',
    'DC': 'Delantero Centro (DC)',
    'DEF': 'Defensor (DEF)',
    'MED': 'Mediocampista (MED)',
    'DEL': 'Delantero (DEL)'
  };
  return map[posUpper] || pos;
}

function getPositionDisplay(p) {
  if (!p) return 'Mediocampista (MC)';
  const raw = p.position || p.positionEs || 'MC';
  if (currentLang === 'es') {
    return p.positionEs || getPositionEs(raw);
  }
  return p.position || p.positionEs || 'CM';
}

function isPositionMatch(playerPos, filterPos) {
  if (!filterPos) return true;
  if (!playerPos) return false;
  
  const pUpper = String(playerPos).toUpperCase().trim();
  const fUpper = String(filterPos).toUpperCase().trim();
  
  if (pUpper === fUpper) return true;
  
  const groups = {
    'GK': ['GK', 'PO', 'POR', 'PORTERO'],
    'POR': ['GK', 'PO', 'POR', 'PORTERO'],
    'DEF': ['DEF', 'CB', 'DFC', 'LB', 'LI', 'RB', 'LD', 'LWB', 'RWB', 'DEFENSOR'],
    'CB': ['CB', 'DFC', 'DEF'],
    'LB': ['LB', 'LI', 'DEF'],
    'RB': ['RB', 'LD', 'DEF'],
    'MED': ['MED', 'CM', 'MC', 'DM', 'MCD', 'AM', 'MCO', 'LM', 'MI', 'RM', 'MD', 'MEDIOCAMPISTA'],
    'CM': ['CM', 'MC', 'MED'],
    'DM': ['DM', 'MCD', 'MED'],
    'AM': ['AM', 'MCO', 'MED'],
    'DEL': ['DEL', 'ST', 'DC', 'CF', 'SD', 'LW', 'EI', 'RW', 'ED', 'DELANTERO'],
    'ST': ['ST', 'DC', 'DEL'],
    'LW': ['LW', 'EI', 'DEL'],
    'RW': ['RW', 'ED', 'DEL']
  };
  
  if (groups[fUpper] && groups[fUpper].includes(pUpper)) return true;
  return false;
}

function getInitials(name) {
  if (!name) return '??';
  const parts = name.split(' ');
  if (parts.length >= 2) {
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  }
  return name.substring(0, 2).toUpperCase();
}

let currentLang = localStorage.getItem('futbolai-lang') || 'es';
const t = key => TRANSLATIONS[currentLang][key] ?? key;

function applyTranslations() {
  // Update all data-i18n elements (text)
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    if (TRANSLATIONS[currentLang][key] !== undefined) {
      el.innerHTML = TRANSLATIONS[currentLang][key];
    }
  });
  // Update all data-i18n-placeholder elements
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.dataset.i18nPlaceholder;
    if (TRANSLATIONS[currentLang][key] !== undefined) {
      el.placeholder = TRANSLATIONS[currentLang][key];
    }
  });
  // Update lang buttons
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === currentLang);
  });
  // Update html lang attribute
  document.documentElement.lang = currentLang;
  // Rebuild dynamic quick prompts on home
  buildHomePrompts();
  // Refresh featured grid labels if rendered
  if (allPlayers.length) {
    populateLeagueFilter();
    initCustomDropdowns();
    renderFeaturedPlayers();
    if (document.getElementById('section-players').classList.contains('active')) {
      renderPlayers();
    }
    if (document.getElementById('section-my-club')?.classList.contains('active')) {
      renderMyClubDashboard();
    }
  }
  // Update welcome message in chat if visible
  const welcome = document.querySelector('.chat-welcome');
  if (welcome) buildChatWelcome(welcome);
}

function buildHomePrompts() {
  const container = document.getElementById('home-quick-prompts');
  if (!container) return;
  container.innerHTML = '';
  ['1','2','3','4'].forEach(n => {
    const btn = document.createElement('button');
    btn.className = 'prompt-chip';
    btn.textContent = t(`prompt${n}_label`);
    btn.onclick = () => quickChat(t(`prompt${n}`));
    container.appendChild(btn);
  });
}

function buildChatWelcome(el) {
  el.innerHTML = `
    <div class="welcome-icon">⚽</div>
    <h3>${t('welcome_title')}</h3>
    <p>${t('welcome_text')}</p>
    <div class="welcome-chips">
      ${[1,2,3,4].map(n => `<button class="prompt-chip" onclick="sendQuick(t('prompt${n}'))">${t(`prompt${n}_label`)}</button>`).join('')}
    </div>
  `;
  // Re-bind onclick properly
  el.querySelectorAll('.prompt-chip').forEach((btn, i) => {
    const n = i + 1;
    btn.onclick = () => sendQuick(t(`prompt${n}`));
  });
}

async function checkBackendStatus() {
  try {
    const res = await fetch(`${API}/health`).catch(() => null);
    const isOk = res && res.ok;
    const badge = document.getElementById('backend-status-badge');
    if (badge) {
      badge.textContent = isOk ? 'ONLINE' : 'OFFLINE';
      badge.className = `status-badge ${isOk ? 'online' : 'offline'}`;
    }
  } catch (e) {
    const badge = document.getElementById('backend-status-badge');
    if (badge) {
      badge.textContent = 'OFFLINE';
      badge.className = 'status-badge offline';
    }
  }
}
window.checkBackendStatus = checkBackendStatus;

function setupMobileMenu() {
  const toggleBtn = document.getElementById('btn-mobile-menu') || document.getElementById('mobile-toggle') || document.querySelector('.hamburger-btn');
  const menu = document.getElementById('mobile-menu') || document.querySelector('.mobile-menu-drawer');
  const overlay = document.getElementById('mobile-menu-overlay') || document.querySelector('.mobile-menu-overlay');

  if (toggleBtn) {
    toggleBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (menu) menu.classList.toggle('active');
      if (overlay) overlay.classList.toggle('active');
    });
  }

  if (overlay) {
    overlay.addEventListener('click', () => {
      closeMobileMenu();
    });
  }

  const mobileNavButtons = document.querySelectorAll('.mobile-nav-links .nav-item');
  mobileNavButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      closeMobileMenu();
    });
  });
}

function closeMobileMenu() {
  const menu = document.getElementById('mobile-menu') || document.querySelector('.mobile-menu-drawer');
  const overlay = document.getElementById('mobile-menu-overlay') || document.querySelector('.mobile-menu-overlay');
  if (menu) menu.classList.remove('active');
  if (overlay) overlay.classList.remove('active');
}

window.setupMobileMenu = setupMobileMenu;
window.closeMobileMenu = closeMobileMenu;

function setupLanguageToggle() {
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const lang = btn.dataset.lang;
      if (lang === currentLang) return;
      currentLang = lang;
      localStorage.setItem('futbolai-lang', lang);
      applyTranslations();
      showToast(lang === 'es' ? '🇪🇸 Idioma cambiado a Español' : '🇬🇧 Language changed to English', 'info');
    });
  });
}

