window.simulateFixture = function(opponentName) {
  const select = document.getElementById('arena-away-select');
  if (select) {
    let exists = false;
    for (let i = 0; i < select.options.length; i++) {
      if (select.options[i].value === opponentName) {
        exists = true;
        break;
      }
    }
    if (!exists && opponentName) {
      const opt = document.createElement('option');
      opt.value = opponentName;
      opt.textContent = opponentName;
      select.appendChild(opt);
    }
    
    select.value = opponentName;
    select.dispatchEvent(new Event('change'));
    document.querySelector('.arena-card')?.scrollIntoView({ behavior: 'smooth' });
  }
};

function setupArenaAwayDropdown() {
  const trigger = document.getElementById('dropdown-trigger-arena-away');
  const menu = document.getElementById('dropdown-menu-arena-away');
  const searchInput = document.getElementById('dropdown-search-arena-away');

  if (trigger && menu && !trigger.dataset.setupDone) {
    trigger.dataset.setupDone = 'true';
    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      document.querySelectorAll('.dropdown-menu').forEach(m => {
        if (m !== menu) m.classList.remove('show');
      });
      menu.classList.toggle('show');
      if (menu.classList.contains('show') && searchInput) {
        searchInput.value = '';
        const user = JSON.parse(localStorage.getItem('scout_ai_user') || '{}');
        const myClub = user.selectedClub || 'FC Barcelona';
        populateArenaAwaySelect('', myClub);
        searchInput.focus();
      }
    });
  }

  if (searchInput && !searchInput.dataset.setupDone) {
    searchInput.dataset.setupDone = 'true';
    searchInput.addEventListener('input', (e) => {
      const user = JSON.parse(localStorage.getItem('scout_ai_user') || '{}');
      const myClub = user.selectedClub || 'FC Barcelona';
      populateArenaAwaySelect(e.target.value, myClub);
    });
    searchInput.addEventListener('click', (e) => {
      e.stopPropagation();
    });
  }
}

const POPULAR_ARENA_TEAMS = [
  'Real Madrid', 'FC Barcelona', 'Manchester City', 'Bayern München', 'Bayern Munich',
  'Paris Saint-Germain', 'Liverpool', 'Arsenal', 'Inter', 'Juventus',
  'Atlético de Madrid', 'Atlético Madrid', 'Chelsea', 'Borussia Dortmund', 'AC Milan',
  'Boca Juniors', 'River Plate', 'CR Flamengo', 'Flamengo', 'Palmeiras',
  'Al-Nassr', 'Al-Hilal', 'Bayer 04 Leverkusen', 'Bayer Leverkusen', 'Tottenham Hotspur',
  'Sevilla FC', 'Real Betis', 'Athletic Club', 'AS Roma', 'Napoli', 'SS Lazio'
];

function getPopularRank(teamName) {
  if (!teamName) return 999;
  const nameLower = teamName.toLowerCase();
  const index = POPULAR_ARENA_TEAMS.findIndex(p => p.toLowerCase() === nameLower || nameLower.includes(p.toLowerCase()));
  return index !== -1 ? index : 999;
}

function isValidTeamName(name) {
  if (!name || typeof name !== 'string') return false;
  const trimmed = name.trim();
  if (trimmed.length < 2) return false;
  if (trimmed.startsWith('"') || trimmed.startsWith('|') || trimmed.startsWith("'")) return false;
  const upper = trimmed.toUpperCase();
  if (upper.includes('N/D') || upper.includes('N/A') || upper.includes('NO DISPONIBLE') || upper.includes('UNDEFINED') || upper.includes('NULL')) return false;
  if (upper.includes('EQUIPOS') || upper.includes('CORRECTOS') || upper.includes('DOCUMENTO') || upper.includes('VER TAMBIÉN') || upper.includes('ACTUAL,')) return false;
  return true;
}

function populateArenaAwaySelect(searchQuery = '', myClubName = '') {
  const optionsContainer = document.getElementById('dropdown-options-arena-away');
  const nativeSelect = document.getElementById('arena-away-select');
  if (!optionsContainer) return;
  
  optionsContainer.innerHTML = '';
  if (nativeSelect) {
    nativeSelect.innerHTML = '<option value="">Selecciona un rival...</option>';
  }

  const query = (searchQuery || '').trim().toLowerCase();
  
  // Filter teams across ALL 1,200+ teams in DB
  const filtered = allTeamsForSim.filter(team => {
    if (!team || !team.name) return false;
    if (!isValidTeamName(team.name)) return false;
    if (myClubName && team.name === myClubName) return false;
    if (!query) return true;
    const nameMatch = team.name.toLowerCase().includes(query);
    const leagueMatch = (team.leagueName || '').toLowerCase().includes(query);
    const countryMatch = (team.country || '').toLowerCase().includes(query);
    return nameMatch || leagueMatch || countryMatch;
  });

  if (!query) {
    // When no search query is typed, sort popular/top tier teams first!
    filtered.sort((a, b) => {
      const rankA = getPopularRank(a.name);
      const rankB = getPopularRank(b.name);
      if (rankA !== rankB) return rankA - rankB;
      return a.name.localeCompare(b.name);
    });
  }

  // Populate native select for fallback
  if (nativeSelect) {
    filtered.forEach(team => {
      const opt = document.createElement('option');
      opt.value = team.name;
      opt.textContent = team.name;
      nativeSelect.appendChild(opt);
    });
  }

  // LIMIT VISUALLY TO MAXIMUM 20 TEAMS
  const visible = filtered.slice(0, 20);

  if (visible.length === 0) {
    const emptyOpt = document.createElement('div');
    emptyOpt.className = 'dropdown-option';
    emptyOpt.style.cursor = 'default';
    emptyOpt.style.color = 'var(--text-3)';
    emptyOpt.textContent = 'Sin resultados';
    optionsContainer.appendChild(emptyOpt);
    return;
  }

  const activeVal = nativeSelect ? nativeSelect.value : '';

  visible.forEach(team => {
    const opt = document.createElement('div');
    opt.className = 'dropdown-option';
    if (activeVal === team.name) opt.classList.add('active');
    opt.dataset.value = team.name;
    const leagueTag = team.leagueName || team.country ? ` (${team.leagueName || team.country})` : '';
    opt.textContent = `${team.name}${leagueTag}`;
    
    opt.addEventListener('click', (e) => {
      e.stopPropagation();
      selectArenaAwayTeam(team.name);
    });
    
    optionsContainer.appendChild(opt);
  });
}

function selectArenaAwayTeam(teamName) {
  const triggerText = document.getElementById('arena-away-trigger-text');
  const menu = document.getElementById('dropdown-menu-arena-away');
  const nativeSelect = document.getElementById('arena-away-select');

  if (triggerText) {
    triggerText.textContent = teamName || 'Selecciona un rival...';
  }
  if (menu) {
    menu.classList.remove('show');
  }
  if (nativeSelect) {
    nativeSelect.value = teamName;
    nativeSelect.dispatchEvent(new Event('change'));
  }
}

// ──────────────── SIMULATION LINEUP EDITOR MODULE ────────────────
window.simCustomRosters = {};
let currentSimStartingXI = [];
let currentSimBench = [];
let selectedSimSlotIndex = 0;
let currentSimPosFilter = '';

function getSimulationHomeRoster(homeName) {
  const user = JSON.parse(localStorage.getItem('scout_ai_user') || '{}');
  const clubName = homeName || user.selectedClub || 'FC Barcelona';

  const savedRaw = localStorage.getItem('sim_custom_roster_' + clubName);
  if (savedRaw) {
    try {
      const parsed = JSON.parse(savedRaw);
      if (parsed.startingXI && Array.isArray(parsed.startingXI) && parsed.startingXI.length > 0) {
        return {
          startingXI: parsed.startingXI,
          bench: parsed.bench || [],
          totalRoster: [...parsed.startingXI, ...(parsed.bench || [])]
        };
      }
    } catch(e) {}
  }

  if (window.simCustomRosters && window.simCustomRosters[clubName] && window.simCustomRosters[clubName].startingXI) {
    return {
      startingXI: window.simCustomRosters[clubName].startingXI,
      bench: window.simCustomRosters[clubName].bench || [],
      totalRoster: [...window.simCustomRosters[clubName].startingXI, ...(window.simCustomRosters[clubName].bench || [])]
    };
  }

  return { startingXI: null, bench: null, totalRoster: null };
}

async function getSimulationAwayRoster(awayName, homeClubName) {
  const user = JSON.parse(localStorage.getItem('scout_ai_user') || '{}');
  const homeClub = homeClubName || user.selectedClub || 'FC Barcelona';

  // 1. Get home team simulation lineup to identify transferred players
  const simHomeData = getSimulationHomeRoster(homeClub);
  const homeStartingXI = simHomeData.startingXI || [];
  const homeBench = simHomeData.bench || [];
  const allHomeSimPlayers = [...homeStartingXI, ...homeBench];

  // Build a Set of names and IDs of players currently in the home team's simulation lineup
  const homePlayerIds = new Set(allHomeSimPlayers.map(p => p.id).filter(Boolean));
  const homePlayerNames = new Set(allHomeSimPlayers.map(p => normalizeString((p.name || '').toLowerCase())));

  // 2. Fetch raw players for away team
  let rawAwayPlayers = await fetchTeamPlayers(awayName);
  if (!rawAwayPlayers || rawAwayPlayers.length === 0) {
    if (window.allPlayers && Array.isArray(window.allPlayers)) {
      rawAwayPlayers = window.allPlayers.filter(p => p.currentTeam === awayName);
    }
  }

  // 3. Exclude any player who has been transferred into the home team's simulation lineup!
  const availableAwayPlayers = (rawAwayPlayers || []).filter(p => {
    if (p.id && homePlayerIds.has(p.id)) return false;
    const pNameNorm = normalizeString((p.name || '').toLowerCase());
    if (homePlayerNames.has(pNameNorm)) return false;
    return true;
  });

  // 4. Use selectTop11CoherentLineup to build the away team's starting XI and bench from their remaining depth!
  const { startingXI, bench } = selectTop11CoherentLineup(availableAwayPlayers);
  const totalRoster = [...startingXI, ...bench];

  return { startingXI, bench, totalRoster, availableAwayPlayers };
}

window.openSimLineupModal = async function() {
  const modal = document.getElementById('sim-lineup-editor-modal');
  if (!modal) return;

  const user = JSON.parse(localStorage.getItem('scout_ai_user') || '{}');
  const myClubName = user.selectedClub || 'FC Barcelona';

  modal.style.setProperty('display', 'flex', 'important');
  document.body.style.overflow = 'hidden';

  // Show platform interactive loading screen overlay
  const loadingOverlay = document.getElementById('sim-modal-loading-overlay');
  const fillBar = document.getElementById('sim-modal-progress-fill');
  const textLabel = document.getElementById('sim-modal-progress-text');

  if (loadingOverlay) {
    loadingOverlay.style.display = 'flex';
    loadingOverlay.style.opacity = '1';
  }
  if (fillBar) fillBar.style.width = '35%';
  if (textLabel) textLabel.textContent = 'Cargando plantilla y base de datos...';

  // Load custom simulation squad if saved, otherwise fetch or generate default
  const savedRaw = localStorage.getItem('sim_custom_roster_' + myClubName);
  if (savedRaw) {
    try {
      const parsed = JSON.parse(savedRaw);
      currentSimStartingXI = parsed.startingXI || [];
      currentSimBench = parsed.bench || [];
    } catch(e) {
      currentSimStartingXI = [];
      currentSimBench = [];
    }
  } else {
    currentSimStartingXI = [];
    currentSimBench = [];
  }

  if (fillBar) fillBar.style.width = '70%';

  if (!currentSimStartingXI || currentSimStartingXI.length === 0) {
    const realPlayers = await fetchTeamPlayers(myClubName);
    if (realPlayers && realPlayers.length > 0) {
      const topLineup = selectTop11CoherentLineup(realPlayers);
      currentSimStartingXI = topLineup.startingXI;
      currentSimBench = topLineup.bench;
    } else {
      currentSimStartingXI = getUserClubStartingXI(myClubName, user);
      currentSimBench = [];
    }
  }

  selectedSimSlotIndex = 0;
  renderSimModalStartingXI();
  renderSimModalBench();
  renderSimModalGlobalPlayers('');
  setupSimModalSearchListeners();

  if (fillBar) fillBar.style.width = '100%';

  // Smoothly fade out loading overlay once data is ready
  setTimeout(() => {
    if (loadingOverlay) {
      loadingOverlay.style.opacity = '0';
      setTimeout(() => {
        loadingOverlay.style.display = 'none';
      }, 300);
    }
  }, 450);
};

window.closeSimLineupModal = function() {
  const modal = document.getElementById('sim-lineup-editor-modal');
  if (modal) modal.style.setProperty('display', 'none', 'important');
  document.body.style.overflow = '';
};

